using ContosoUniversity.Data;
using ContosoUniversity.Models;
using Microsoft.EntityFrameworkCore;
using System;
using System.Collections.Generic;

namespace ContosoUniversity.Tests.TestHelpers;

public static class TestDbContextFactory
{
    public static SchoolContext Create(string? dbName = null)
    {
        var options = new DbContextOptionsBuilder<SchoolContext>()
            .UseInMemoryDatabase(databaseName: dbName ?? Guid.NewGuid().ToString())
            .Options;

        var context = new SchoolContext(options);
        context.Database.EnsureCreated();
        return context;
    }

    public static SchoolContext CreateWithSeedData(string? dbName = null)
    {
        var context = Create(dbName);
        SeedData(context);
        return context;
    }

    public static void SeedData(SchoolContext context)
    {
        var instructors = new Instructor[]
        {
            new Instructor { FirstMidName = "Kim", LastName = "Abercrombie", HireDate = DateTime.Parse("1995-03-11") },
            new Instructor { FirstMidName = "Fadi", LastName = "Fakhouri", HireDate = DateTime.Parse("2002-07-06") },
            new Instructor { FirstMidName = "Roger", LastName = "Harui", HireDate = DateTime.Parse("1998-07-01") },
        };
        context.Instructors.AddRange(instructors);
        context.SaveChanges();

        var departments = new Department[]
        {
            new Department { Name = "English", Budget = 350000, StartDate = DateTime.Parse("2007-09-01"), InstructorID = instructors[0].ID },
            new Department { Name = "Mathematics", Budget = 100000, StartDate = DateTime.Parse("2007-09-01"), InstructorID = instructors[1].ID },
            new Department { Name = "Engineering", Budget = 350000, StartDate = DateTime.Parse("2007-09-01"), InstructorID = instructors[2].ID },
        };
        context.Departments.AddRange(departments);
        context.SaveChanges();

        var courses = new Course[]
        {
            new Course { CourseID = 1050, Title = "Chemistry", Credits = 3, DepartmentID = departments[2].DepartmentID },
            new Course { CourseID = 4022, Title = "Microeconomics", Credits = 3, DepartmentID = departments[1].DepartmentID },
            new Course { CourseID = 2021, Title = "Composition", Credits = 3, DepartmentID = departments[0].DepartmentID },
        };
        context.Courses.AddRange(courses);
        context.SaveChanges();

        var students = new Student[]
        {
            new Student { FirstMidName = "Carson", LastName = "Alexander", EnrollmentDate = DateTime.Parse("2010-09-01") },
            new Student { FirstMidName = "Meredith", LastName = "Alonso", EnrollmentDate = DateTime.Parse("2012-09-01") },
            new Student { FirstMidName = "Arturo", LastName = "Anand", EnrollmentDate = DateTime.Parse("2013-09-01") },
        };
        context.Students.AddRange(students);
        context.SaveChanges();

        var enrollments = new Enrollment[]
        {
            new Enrollment { StudentID = students[0].ID, CourseID = courses[0].CourseID, Grade = Grade.A },
            new Enrollment { StudentID = students[1].ID, CourseID = courses[1].CourseID, Grade = Grade.B },
            new Enrollment { StudentID = students[2].ID, CourseID = courses[2].CourseID },
        };
        context.Enrollments.AddRange(enrollments);
        context.SaveChanges();

        // Add course assignments
        var assignments = new CourseAssignment[]
        {
            new CourseAssignment { CourseID = courses[0].CourseID, InstructorID = instructors[0].ID },
            new CourseAssignment { CourseID = courses[1].CourseID, InstructorID = instructors[1].ID },
            new CourseAssignment { CourseID = courses[2].CourseID, InstructorID = instructors[2].ID },
        };
        context.CourseAssignments.AddRange(assignments);
        context.SaveChanges();

        // Add office assignments
        var offices = new OfficeAssignment[]
        {
            new OfficeAssignment { InstructorID = instructors[1].ID, Location = "Smith 17" },
            new OfficeAssignment { InstructorID = instructors[2].ID, Location = "Gowan 27" },
        };
        context.OfficeAssignments.AddRange(offices);
        context.SaveChanges();
    }
}

