using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.TestHelpers;
using Microsoft.EntityFrameworkCore;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Data;

public class DbInitializerTests
{
    [Fact]
    public void Initialize_EmptyDatabase_SeedsStudents()
    {
        using var context = TestDbContextFactory.Create();

        DbInitializer.Initialize(context);

        Assert.Equal(8, context.Students.Count());
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsInstructors()
    {
        using var context = TestDbContextFactory.Create();

        DbInitializer.Initialize(context);

        Assert.Equal(5, context.Instructors.Count());
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsDepartments()
    {
        using var context = TestDbContextFactory.Create();

        DbInitializer.Initialize(context);

        Assert.Equal(4, context.Departments.Count());
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsCourses()
    {
        using var context = TestDbContextFactory.Create();

        DbInitializer.Initialize(context);

        Assert.Equal(7, context.Courses.Count());
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsEnrollments()
    {
        using var context = TestDbContextFactory.Create();

        DbInitializer.Initialize(context);

        Assert.Equal(11, context.Enrollments.Count());
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsOfficeAssignments()
    {
        using var context = TestDbContextFactory.Create();

        DbInitializer.Initialize(context);

        Assert.Equal(3, context.OfficeAssignments.Count());
    }

    [Fact]
    public void Initialize_EmptyDatabase_SeedsCourseAssignments()
    {
        using var context = TestDbContextFactory.Create();

        DbInitializer.Initialize(context);

        Assert.Equal(8, context.CourseAssignments.Count());
    }

    [Fact]
    public void Initialize_ExistingData_DoesNotReseed()
    {
        using var context = TestDbContextFactory.Create();
        // Add one student to simulate existing data
        context.Students.Add(new Student
        {
            FirstMidName = "Existing",
            LastName = "Student",
            EnrollmentDate = DateTime.Parse("2020-01-01")
        });
        context.SaveChanges();

        DbInitializer.Initialize(context);

        // Should still have only the one manually added student
        Assert.Equal(1, context.Students.Count());
        Assert.Equal("Existing", context.Students.First().FirstMidName);
    }

    [Fact]
    public void Initialize_SeedsCorrectStudentNames()
    {
        using var context = TestDbContextFactory.Create();

        DbInitializer.Initialize(context);

        var students = context.Students.OrderBy(s => s.LastName).ToList();
        Assert.Equal("Alexander", students[0].LastName);
        Assert.Equal("Carson", students[0].FirstMidName);
    }

    [Fact]
    public void Initialize_SeedsCorrectInstructorNames()
    {
        using var context = TestDbContextFactory.Create();

        DbInitializer.Initialize(context);

        var instructors = context.Instructors.OrderBy(i => i.LastName).ToList();
        Assert.Equal("Abercrombie", instructors[0].LastName);
        Assert.Equal("Kim", instructors[0].FirstMidName);
    }

    [Fact]
    public void Initialize_SeedsCorrectDepartmentNames()
    {
        using var context = TestDbContextFactory.Create();

        DbInitializer.Initialize(context);

        var deptNames = context.Departments.Select(d => d.Name).OrderBy(n => n).ToList();
        Assert.Contains("English", deptNames);
        Assert.Contains("Mathematics", deptNames);
        Assert.Contains("Engineering", deptNames);
        Assert.Contains("Economics", deptNames);
    }

    [Fact]
    public void Initialize_SeedsCorrectCourseTitles()
    {
        using var context = TestDbContextFactory.Create();

        DbInitializer.Initialize(context);

        var courseTitles = context.Courses.Select(c => c.Title).ToList();
        Assert.Contains("Chemistry", courseTitles);
        Assert.Contains("Microeconomics", courseTitles);
        Assert.Contains("Calculus", courseTitles);
        Assert.Contains("Composition", courseTitles);
    }

    [Fact]
    public void Initialize_DepartmentsHaveAdministrators()
    {
        using var context = TestDbContextFactory.Create();

        DbInitializer.Initialize(context);

        var departments = context.Departments.ToList();
        Assert.All(departments, d => Assert.NotNull(d.InstructorID));
    }

    [Fact]
    public void Initialize_EnrollmentsHaveGrades()
    {
        using var context = TestDbContextFactory.Create();

        DbInitializer.Initialize(context);

        var enrollments = context.Enrollments.ToList();
        // Not all enrollments have grades (some are null)
        var withGrades = enrollments.Where(e => e.Grade != null).ToList();
        var withoutGrades = enrollments.Where(e => e.Grade == null).ToList();
        Assert.NotEmpty(withGrades);
        Assert.NotEmpty(withoutGrades);
    }

    [Fact]
    public void Initialize_CoursesHaveValidCredits()
    {
        using var context = TestDbContextFactory.Create();

        DbInitializer.Initialize(context);

        var courses = context.Courses.ToList();
        Assert.All(courses, c => Assert.InRange(c.Credits, 1, 5));
    }

    [Fact]
    public void Initialize_MultipleCallsOnEmptyDb_OnlySeedsOnce()
    {
        using var context = TestDbContextFactory.Create();

        DbInitializer.Initialize(context);
        DbInitializer.Initialize(context);

        // Second call should not add more data (early return due to Students.Any())
        Assert.Equal(8, context.Students.Count());
    }
}

