using ContosoUniversity.Models;
using ContosoUniversity.Tests.TestHelpers;
using System;
using System.Collections.Generic;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests;

public class PaginatedListTests
{
    [Fact]
    public void Create_ReturnsCorrectPageSize()
    {
        var items = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(items, 1, 10);

        Assert.Equal(10, result.Count);
    }

    [Fact]
    public void Create_FirstPage_ContainsFirstItems()
    {
        var items = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(items, 1, 10);

        Assert.Equal(1, result[0]);
        Assert.Equal(10, result[9]);
    }

    [Fact]
    public void Create_SecondPage_ContainsCorrectItems()
    {
        var items = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(items, 2, 10);

        Assert.Equal(11, result[0]);
        Assert.Equal(20, result[9]);
    }

    [Fact]
    public void Create_LastPage_ContainsRemainingItems()
    {
        var items = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(items, 3, 10);

        Assert.Equal(5, result.Count);
        Assert.Equal(21, result[0]);
        Assert.Equal(25, result[4]);
    }

    [Fact]
    public void Create_SetsPageIndex()
    {
        var items = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(items, 2, 10);

        Assert.Equal(2, result.PageIndex);
    }

    [Fact]
    public void Create_SetsTotalPages()
    {
        var items = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(items, 1, 10);

        Assert.Equal(3, result.TotalPages);
    }

    [Fact]
    public void Create_ExactDivision_SetsTotalPagesCorrectly()
    {
        var items = Enumerable.Range(1, 20).AsQueryable();

        var result = PaginatedList<int>.Create(items, 1, 10);

        Assert.Equal(2, result.TotalPages);
    }

    [Fact]
    public void HasPreviousPage_FirstPage_ReturnsFalse()
    {
        var items = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(items, 1, 10);

        Assert.False(result.HasPreviousPage);
    }

    [Fact]
    public void HasPreviousPage_SecondPage_ReturnsTrue()
    {
        var items = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(items, 2, 10);

        Assert.True(result.HasPreviousPage);
    }

    [Fact]
    public void HasNextPage_FirstPage_ReturnsTrue()
    {
        var items = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(items, 1, 10);

        Assert.True(result.HasNextPage);
    }

    [Fact]
    public void HasNextPage_LastPage_ReturnsFalse()
    {
        var items = Enumerable.Range(1, 25).AsQueryable();

        var result = PaginatedList<int>.Create(items, 3, 10);

        Assert.False(result.HasNextPage);
    }

    [Fact]
    public void Constructor_SetsPropertiesCorrectly()
    {
        var items = new List<int> { 1, 2, 3 };

        var result = new PaginatedList<int>(items, 10, 2, 5);

        Assert.Equal(2, result.PageIndex);
        Assert.Equal(2, result.TotalPages); // ceil(10/5) = 2
        Assert.Equal(3, result.Count);
    }

    [Fact]
    public void Create_EmptySource_ReturnsEmptyList()
    {
        var items = Enumerable.Empty<int>().AsQueryable();

        var result = PaginatedList<int>.Create(items, 1, 10);

        Assert.Empty(result);
        Assert.Equal(0, result.TotalPages);
    }

    [Fact]
    public void Create_SingleItemSource_ReturnsOneItem()
    {
        var items = new[] { 42 }.AsQueryable();

        var result = PaginatedList<int>.Create(items, 1, 10);

        Assert.Single(result);
        Assert.Equal(42, result[0]);
        Assert.Equal(1, result.TotalPages);
    }
}

